(()=>{if(location.pathname!=='/')return;const main=document.querySelector('main');if(!main||document.querySelector('.experience-section'))return;const sec=document.createElement('section');sec.className='experience-section';sec.innerHTML='<div class="wrap"><div class="head"><span class="eyebrow">A smoother way to get started</span><h2>From your device to your first stream in four clear steps.</h2><p class="muted">A simple, customer-first path built around compatible players and helpful setup guidance.</p></div><div class="grid four-step"><article class="card feature"><div class="num">01</div><h3>Compare plans</h3><p>Review each duration and choose the viewing period that suits you.</p><a href="/pricing/">View plans →</a></article><article class="card feature"><div class="num">02</div><h3>Choose a player</h3><p>See compatible app options and device-friendly installation resources.</p><a href="/apps/">View apps →</a></article><article class="card feature"><div class="num">03</div><h3>Follow your guide</h3><p>Use a clear setup guide for your TV, mobile device or streaming box.</p><a href="/guides/">Read guides →</a></article><article class="card feature"><div class="num">04</div><h3>Get help</h3><p>Use the contact page whenever you need plan or setup assistance.</p><a href="/contact/">Contact team →</a></article></div></div></section><section class="device-section"><div class="wrap"><div class="head"><span class="eyebrow">Compatible screens</span><h2>Designed around the devices you already use.</h2></div><div class="device-grid">Fire TV Stick · Smart TV · Android TV · iPhone & iPad · Windows · MAG · Enigma2 · TiviMate</div></div></section>';main.insertBefore(sec,main.querySelector('.smart-next')||null);const style=document.createElement('style');style.textContent='.four-step{grid-template-columns:repeat(4,1fr)}.device-section{padding-top:20px}.device-grid{padding:23px;border:1px solid #384a92;border-radius:14px;background:#111a3bb8;color:#d7dfff;word-spacing:14px}@media(max-width:800px){.four-step{grid-template-columns:1fr}}';document.head.append(style)})();
